cd /workspace && node -e "
const Database = require('better-sqlite3');
const { v4: uuidv4 } = require('uuid');
const db = new Database('world.db');

const selfContact = db.prepare('SELECT * FROM ts_contacts WHERE is_self = 1').get();
const recipient = db.prepare(\"SELECT * FROM ts_contacts WHERE phone_number = '+1-347-555-0169'\").get();

const messageId = uuidv4();
const now = Date.now() / 1000;

db.prepare(\`INSERT INTO ts_messages (message_id, sender_person_id, sender_phone_number, recipient_person_id, recipient_phone_number, content, creation_timestamp) VALUES (?, ?, ?, ?, ?, ?, ?)\`).run(
  messageId,
  selfContact.person_id,
  selfContact.phone_number,
  recipient ? recipient.person_id : null,
  '+1-347-555-0169',
  'Hi Daniel, just checking in—let me know if you\\'re available for a quick call this week. Thanks!',
  now
);

console.log(JSON.stringify({ ok: true, message_id: messageId }, null, 2));
db.close();
" 2>&1

